// @contract
// intencao: Formatar lista de NFs para instrucoes de ZIP com nomes de arquivo padronizados
// entrada: array de itens com {data_emissao, estabelecimento, categoria, valor_total, message_id}
// criterio_sucesso: retorna array nfs com nomes unicos no formato NN_DATA_ESTABELECIMENTO.jpg
// saida_nfs: array com {ordem, arquivo, estabelecimento, categoria, valor, data, message_id}
// saida_total: quantidade inteira de NFs processadas
// @end-contract

const nfs = $input.all().map((item, i) => ({
  ordem: i + 1,
  arquivo: (i + 1).toString().padStart(2, '0') + '_' + (item.json.data_emissao || 'sem_data') + '_' + (item.json.estabelecimento || 'NF').replace(/[^a-zA-Z0-9]/g, '_').substring(0, 30) + '.jpg',
  estabelecimento: item.json.estabelecimento,
  categoria: item.json.categoria,
  valor: item.json.valor_total,
  data: item.json.data_emissao,
  message_id: item.json.message_id
}));
return [{ json: { nfs, total: nfs.length } }];

const viagens = $input.first().json.viagens || [];

const fmt = (v) => Number(v).toLocaleString('pt-BR', {style:'currency', currency:'BRL'});
const fmtD = (d) => d ? new Date(d).toLocaleDateString('pt-BR') : '-';
const toTitle = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : '';
const CAT = {alimentacao:'Alimentacao',combustivel:'Combustivel',hospedagem:'Hospedagem',transporte:'Transporte',pedagio:'Pedagio',outros:'Outros'};
const ST_L = {ativa:'Ativa',encerrada:'Encerrada',aprovada:'Aprovada'};
const ST_C = {ativa:'#4ade80',encerrada:'#60a5fa',aprovada:'#c084fc'};
const ST_B = {ativa:'#1a3a2a',encerrada:'#1a2a3a',aprovada:'#2a1a3a'};

const totalGeral = viagens.reduce((acc, v) => {
  const desps = Array.isArray(v.despesas) ? v.despesas : JSON.parse(v.despesas || '[]');
  return acc + desps.reduce((s,d) => s + Number(d.valor_total||0), 0);
}, 0);

const renderViagem = (v, idx) => {
  const desps = Array.isArray(v.despesas) ? v.despesas : JSON.parse(v.despesas || '[]');
  const total = desps.reduce((s,d) => s + Number(d.valor_total||0), 0);
  const cats = desps.reduce((a,d) => { a[d.categoria]=(a[d.categoria]||0)+Number(d.valor_total||0); return a; }, {});
  const cor = ST_C[v.status] || '#60a5fa';
  const bg = ST_B[v.status] || '#1a2a3a';
  const nomeViagem = toTitle(v.nome_viagem || 'Sem nome');
  const BS = 'border-radius:4px;padding:3px 8px;font-size:12px;cursor:pointer;border:1px solid';

  const linhasDesp = desps.length === 0
    ? '<tr><td colspan="5" style="padding:16px;text-align:center;color:#4a5568;font-size:13px">Nenhuma despesa registrada.</td></tr>'
    : desps.map((d,i) => {
        const tf = [d.tipo_pagador, d.forma_pagamento].filter(Boolean).join('+') || '-';
        const isV = d.validado_manualmente === true;
        const isR = d.validado_manualmente === false;
        const acao = (!isV && !isR)
          ? `<button onclick="act('validar-despesa',{despesa_id:${d.id}})" style="${BS} #4ade80;background:#1a3a1a;color:#4ade80">&#10003;</button> <button onclick="act('rejeitar-despesa',{despesa_id:${d.id}})" style="${BS} #f87171;background:#3a1a1a;color:#f87171">&#10007;</button>`
          : `<span style="font-size:10px;color:${isV?'#4ade80':'#f87171'}">${isV?'ok':'rej'}</span>`;
        return `<tr style="background:${i%2?'#0a0a0a':'transparent'};border-top:1px solid #1a1a1a">
          <td style="padding:10px 12px;font-size:12px;color:#64748b;white-space:nowrap">${fmtD(d.data_emissao)}</td>
          <td style="padding:10px 12px;font-size:13px;color:#e2e8f0">${d.estabelecimento}<br><span style="font-size:10px;color:#4a5568">${CAT[d.categoria]||d.categoria}</span></td>
          <td style="padding:10px 12px;font-size:11px;color:#64748b;white-space:nowrap">${tf}</td>
          <td style="padding:10px 12px;font-size:14px;font-weight:700;color:#4ade80;text-align:right;white-space:nowrap">${fmt(d.valor_total)}</td>
          <td style="padding:6px 8px;text-align:center;white-space:nowrap">${acao}</td>
        </tr>`;
      }).join('')
    + `<tr style="background:#0d1a0d;border-top:1px solid #2d2d2d">
        <td colspan="3" style="padding:10px 12px;font-size:11px;font-weight:700;color:#4a5568;text-transform:uppercase">Total</td>
        <td style="padding:10px 12px;font-size:15px;font-weight:700;color:#4ade80;text-align:right">${fmt(total)}</td>
        <td></td>
      </tr>`;

  const linhasCats = Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([cat,val]) => {
    const pct = total > 0 ? ((val/total)*100).toFixed(1) : 0;
    return `<div style="margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:4px">
        <span style="color:#94a3b8">${CAT[cat]||cat}</span>
        <span style="color:#f1f5f9;font-weight:600">${fmt(val)}</span>
      </div>
      <div style="height:4px;background:#1e1e1e;border-radius:99px">
        <div style="height:4px;border-radius:99px;background:linear-gradient(90deg,#3b82f6,#8b5cf6);width:${pct}%"></div>
      </div>
    </div>`;
  }).join('');

  return `<details style="background:#111;border:1px solid #1e1e1e;border-radius:12px;margin-bottom:14px;overflow:hidden" ${idx===0?'open':''}>
    <summary style="padding:14px 16px;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:flex-start;gap:10px">
      <div style="flex:1;min-width:0">
        <div style="font-size:10px;color:#4a5568;margin-bottom:2px">Viagem #${v.id}</div>
        <div style="font-size:16px;font-weight:700;color:#f1f5f9;word-break:break-word">${nomeViagem}</div>
        <div style="font-size:12px;color:#64748b;margin-top:3px">${v.funcionario_nome} &middot; ${fmtD(v.data_inicio)} &rarr; ${fmtD(v.data_fim)}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0">
        <span style="font-size:10px;padding:3px 9px;border-radius:99px;background:${bg};color:${cor}">${ST_L[v.status]||v.status}</span>
        <span style="font-size:15px;font-weight:700;color:#4ade80">${fmt(total)}</span>
      </div>
    </summary>
    <div style="padding:0 14px 14px">
      <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:12px">
        <div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:8px;padding:10px 12px">
          <div style="font-size:10px;color:#4a5568;margin-bottom:4px">Total</div>
          <div style="font-size:17px;font-weight:700;color:#4ade80">${fmt(total)}</div>
        </div>
        <div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:8px;padding:10px 12px">
          <div style="font-size:10px;color:#4a5568;margin-bottom:4px">Notas fiscais</div>
          <div style="font-size:17px;font-weight:700;color:#60a5fa">${desps.length}</div>
        </div>
      </div>
      ${linhasCats ? `<div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:8px;padding:12px;margin-bottom:12px">
        <div style="font-size:10px;color:#4a5568;margin-bottom:10px;text-transform:uppercase;letter-spacing:.08em">Por categoria</div>
        ${linhasCats}
      </div>` : ''}
      <div style="background:#0d0d0d;border:1px solid #1e1e1e;border-radius:8px;overflow:hidden;margin-bottom:${v.status==='encerrada'?'12':'0'}px">
        <div style="padding:10px 12px;font-size:10px;color:#4a5568;text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid #1e1e1e">Despesas</div>
