          <tbody>${linhasDesp}</tbody>
        </table>
      </div>
      ${v.status==='encerrada'?`<button onclick="act('aprovar',{viagem_id:${v.id}})" style="width:100%;padding:11px;background:#1a1a3a;border:1px solid #3730a3;border-radius:8px;color:#818cf8;font-size:13px;cursor:pointer;font-weight:600">Aprovar esta viagem</button>`:''}
    </div>
  </details>`;
